INSERT INTO cars (name, brand, category, price_per_day, image, seats, transmission, fuel, available, description, year, mileage, features, images) VALUES
  ('Rolls-Royce Phantom', 'Rolls-Royce', 'Luxury Sedan', 1500, '/placeholder.svg', 5, 'Automatic', 'Gasoline', 1, 'The Rolls-Royce Phantom represents the pinnacle of automotive luxury. This masterpiece combines timeless elegance with cutting-edge technology, featuring a hand-crafted interior with the finest leather and wood veneers. Experience unparalleled comfort and prestige with whisper-quiet cabin and effortless V12 power.', 2024, 'Unlimited', '["Premium Sound System","Starlight Headliner","Massage Seats","Champagne Cooler","Rear Entertainment","Suicide Doors","Hand-Crafted Interior","Advanced Safety Systems"]', '[]'),
  ('Bentley Continental GT', 'Bentley', 'Luxury Coupe', 1200, '/placeholder.svg', 4, 'Automatic', 'Gasoline', 1, 'The Bentley Continental GT is the ultimate grand tourer, blending breathtaking performance with handcrafted luxury. Powered by a mighty W12 engine, this British icon delivers exhilarating speed while cocooning passengers in sumptuous comfort. Perfect for those who demand both power and prestige.', 2024, 'Unlimited', '["W12 Twin-Turbo Engine","Diamond-Quilted Leather","Rotating Display","Naim Audio System","Adaptive Cruise Control","Night Vision","Heated & Ventilated Seats","Panoramic Sunroof"]', '[]'),
  ('Mercedes-Benz S-Class', 'Mercedes-Benz', 'Luxury Sedan', 800, '/placeholder.svg', 5, 'Automatic', 'Hybrid', 1, 'The Mercedes-Benz S-Class sets the benchmark for luxury sedans worldwide. This plug-in hybrid combines eco-conscious engineering with opulent comfort and cutting-edge technology. Experience the future of luxury mobility with intelligent drive systems and a serene, tech-forward cabin.', 2024, 'Unlimited', '["Plug-in Hybrid System","MBUX Infotainment","Burmester 3D Sound","Executive Rear Seats","Ambient Lighting (64 colors)","Active Suspension","Head-Up Display","Wireless Charging"]', '[]'),
  ('Porsche 911 Turbo', 'Porsche', 'Sports Car', 1000, '/placeholder.svg', 4, 'Automatic', 'Gasoline', 0, 'The legendary Porsche 911 Turbo delivers pure driving exhilaration with its twin-turbocharged flat-six engine and iconic design. This sports car icon offers blistering acceleration, precise handling, and everyday usability. Experience automotive perfection with German engineering at its finest.', 2024, 'Limited to 200km/day', '["Twin-Turbo Flat-Six Engine","PDK Transmission","Sport Chrono Package","PASM Suspension","Porsche Track Precision App","Sport Exhaust System","Adaptive Sport Seats","Launch Control"]', '[]'),
  ('Range Rover Autobiography', 'Land Rover', 'Luxury SUV', 900, '/placeholder.svg', 7, 'Automatic', 'Diesel', 1, 'The Range Rover Autobiography represents the pinnacle of luxury SUVs, offering unmatched refinement, capability, and prestige. Whether navigating city streets or exploring off-road terrain, this flagship SUV delivers supreme comfort with its spacious cabin and advanced technology.', 2024, 'Unlimited', '["Terrain Response 2","Air Suspension","Windsor Leather Interior","Meridian Sound System","Configurable Ambient Lighting","Panoramic Roof","Powered Gesture Tailgate","Wade Sensing"]', '[]'),
  ('Lamborghini Urus', 'Lamborghini', 'Super SUV', 1800, '/placeholder.svg', 5, 'Automatic', 'Gasoline', 1, 'The Lamborghini Urus redefines the super SUV category with Italian flair and supercar performance. This bold statement on wheels combines the soul of a sports car with the versatility of an SUV, featuring a powerful V8 engine and unmistakable Lamborghini design language.', 2024, 'Limited to 150km/day', '["Twin-Turbo V8 Engine","Anima Drive Modes","Carbon Ceramic Brakes","Tamburo Driving Mode Selector","Premium Alcantara Interior","Bang & Olufsen Audio","Active Aerodynamics","Rear-Wheel Steering"]', '[]');
